import { Injectable } from '@angular/core';
import { Observable, BehaviorSubject, throwError } from 'rxjs';
import { tap } from 'rxjs/operators';
import { AdminAuthService } from '../../../../libs/openapi/src/api/admin-auth.service';
import { ApiAdminAuthRefreshTokenPostRequest } from '../../../../libs/openapi/src/model/api-admin-auth-refresh-token-post-request';
import { ApiAdminAuthLoginPostRequest } from '../../../../libs/openapi/src/model/api-admin-auth-login-post-request';
import { ApiAdminAuthLoginPost200Response } from '../../../../libs/openapi/src/model/api-admin-auth-login-post200-response';
import { ApiAdminAuthLoginPost202Response } from '../../../../libs/openapi/src';

// Interface for password setup response (202)
interface PasswordSetupResponse {
  status: boolean;
  needsPasswordSetup: boolean;
  message: string;
  data: {
    email: string;
  };
}

// Union type for all possible login response types
type LoginResponse =
  | ApiAdminAuthLoginPost200Response
  | PasswordSetupResponse
  | ApiAdminAuthLoginPost202Response;

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private isRefreshingToken = false;
  private refreshTokenSubject: BehaviorSubject<string | null> =
    new BehaviorSubject<string | null>(null);

  constructor(private adminAuthService: AdminAuthService) {}

  /**
   * Login with username and password
   * Returns either a successful login response with tokens or a password setup needed response
   */
  login(
    username: string,
    password: string,
    rememberMe: boolean = false
  ): Observable<LoginResponse> {
    const loginRequest: ApiAdminAuthLoginPostRequest = {
      email: username,
      password: password,
      rememberMe: rememberMe,
    };

    return this.adminAuthService.apiAdminAuthLoginPost(loginRequest).pipe(
      tap((response: LoginResponse) => {
        // Only store tokens if this is a successful auth response (not a password setup response)
        if (!('needsPasswordSetup' in response) && response.data?.accessToken) {
          this.storeTokens(
            response.data.accessToken,
            response.data.refreshToken
          );
        }
      })
    );
  }

  /**
   * Store authentication tokens in localStorage
   */
  private storeTokens(accessToken: string, refreshToken: string): void {
    localStorage.setItem('accessToken', accessToken);
    localStorage.setItem('refreshToken', refreshToken);
  }

  /**
   * Get the stored access token
   */
  getAccessToken(): string | null {
    return localStorage.getItem('accessToken');
  }

  /**
   * Get the stored refresh token
   */
  getRefreshToken(): string | null {
    return localStorage.getItem('refreshToken');
  }

  /**
   * Clear all authentication tokens
   */
  clearTokens(): void {
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
  }

  /**
   * Check if user is logged in
   */
  isLoggedIn(): boolean {
    return !!this.getAccessToken();
  }

  /**
   * Logout user by clearing tokens
   */
  logout(): void {
    this.clearTokens();
  }

  /**
   * Refresh the access token using the refresh token
   */
  refreshToken(): Observable<ApiAdminAuthLoginPost200Response> {
    const refreshToken = this.getRefreshToken();

    if (!refreshToken) {
      return throwError(() => new Error('No refresh token available'));
    }

    const refreshRequest: ApiAdminAuthRefreshTokenPostRequest = {
      refreshToken: refreshToken,
    };

    return this.adminAuthService
      .apiAdminAuthRefreshTokenPost(refreshRequest)
      .pipe(
        tap((response) => {
          this.storeTokens(
            response.data.accessToken,
            response.data.refreshToken
          );
          this.refreshTokenSubject.next(response.data.accessToken);
        })
      );
  }

  /**
   * Check if a token refresh is in progress
   */
  isRefreshingTokenInProgress(): boolean {
    return this.isRefreshingToken;
  }

  /**
   * Set the token refresh status
   */
  setRefreshingToken(isRefreshing: boolean): void {
    this.isRefreshingToken = isRefreshing;
  }

  /**
   * Get the refresh token subject as an observable
   */
  getRefreshTokenSubject(): Observable<string | null> {
    return this.refreshTokenSubject.asObservable();
  }

  /**
   * Reset the refresh token subject
   */
  resetRefreshTokenSubject(): void {
    this.refreshTokenSubject.next(null);
  }
}
